"""Customizes the Android project generated by `flutter create`.
Run once after `flutter create . --platforms=android ...` (CI does it too):

    python3 tools/release/prepare_android.py

  * app name, Lolo launcher icon, orange native splash
  * no INTERNET permission; photo-saving permission only for Android <= 9
  * R8/ProGuard keep rules: release builds shrink code, and without these
    rules plugin bridges (shared_preferences, path_provider, gal, soloud)
    get stripped -> "NoSuchMethodError ... SharedPreferencesApiRegistrar".
"""
import glob, os, re, shutil

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
A = os.path.join(ROOT, "android", "app")
if not os.path.isdir(A):
    raise SystemExit("android/ not found: run `flutter create . --platforms=android --org com.colorland --project-name colorland` first")

# ---- manifest
m_path = os.path.join(A, "src", "main", "AndroidManifest.xml")
m = open(m_path).read()
m = m.replace('android:label="colorland"', 'android:label="ColorLand"')
m = re.sub(r'\s*<uses-permission android:name="android.permission.INTERNET"\s*/>', '', m)
if "WRITE_EXTERNAL_STORAGE" not in m:
    m = m.replace("<application", '<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="28"/>\n    <application', 1)
open(m_path, "w").write(m)

# ---- icon
for d in ["mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi"]:
    src = os.path.join(ROOT, "tools", "icon", f"mipmap-{d}", "ic_launcher.png")
    dst = os.path.join(A, "src", "main", "res", f"mipmap-{d}", "ic_launcher.png")
    if os.path.exists(os.path.dirname(dst)): shutil.copy(src, dst)

# ---- splash color
vals = os.path.join(A, "src", "main", "res", "values")
os.makedirs(vals, exist_ok=True)
open(os.path.join(vals, "colors.xml"), "w").write(
    '<?xml version="1.0" encoding="utf-8"?>\n<resources><color name="splash">#FFB37A</color></resources>\n')
for f in glob.glob(os.path.join(A, "src", "main", "res", "drawable*", "launch_background.xml")):
    s = open(f).read()
    s = s.replace('<item android:drawable="?android:colorBackground" />', '<item android:drawable="@color/splash" />')
    s = s.replace('<item android:drawable="@android:color/white" />', '<item android:drawable="@color/splash" />')
    open(f, "w").write(s)

# ---- ProGuard / R8 keep rules
open(os.path.join(A, "proguard-rules.pro"), "w").write("""# ColorLand: keep Flutter plugin bridges intact in release builds.
-keep class io.flutter.** { *; }
-keep class io.flutter.plugins.** { *; }
-keep class io.flutter.plugins.sharedpreferences.** { *; }
-keep class io.flutter.plugins.pathprovider.** { *; }
-keep class dev.flutter.pigeon.** { *; }
-keep class flutter.soloud.** { *; }
-keep class studio.midoridesign.gal.** { *; }
-keep class kotlin.coroutines.** { *; }
-keep class kotlinx.coroutines.** { *; }
-keepclassmembers class * { @androidx.annotation.Keep *; }
-dontwarn io.flutter.embedding.**
-dontwarn kotlinx.coroutines.**
""")
g_kts = os.path.join(A, "build.gradle.kts"); g_groovy = os.path.join(A, "build.gradle")
if os.path.exists(g_kts):
    s = open(g_kts).read()
    if "proguard-rules.pro" not in s:
        s = re.sub(r'(release\s*\{)', r'\1\n            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")', s, count=1)
        open(g_kts, "w").write(s)
elif os.path.exists(g_groovy):
    s = open(g_groovy).read()
    if "proguard-rules.pro" not in s:
        s = re.sub(r'(release\s*\{)', r"\1\n            proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'", s, count=1)
        open(g_groovy, "w").write(s)
print("android project prepared")
